        "BEGIN IMMEDIATE; UPDATE accounts SET balance=balance-{amount} WHERE id=1; UPDATE accounts SET balance=balance+{amount} WHERE id=2; COMMIT;"
    )
}

fn main() {
    println!("{}", transfer_sql(10));
}

